import React, { useContext, useRef, useSyncExternalStore } from 'react';

export const CONSULT_ALL_SERVICES_OPTION = 'all_services';

export interface ConsultBrowserSelection {
  selectedCountry?: string;
  selectedService: string;
  countryManuallySelected: boolean;
  serviceManuallySelected: boolean;
  selectedServiceIndex: number;
  preferListFirstCountry: boolean;
}

export interface ConsultBrowserStore {
  getSelection: () => ConsultBrowserSelection;
  subscribe: (listener: () => void) => () => void;
  updateSelection: (
    updater: (current: ConsultBrowserSelection) => ConsultBrowserSelection,
  ) => void;
}

const INITIAL_SELECTION: ConsultBrowserSelection = {
  selectedCountry: undefined,
  selectedService: CONSULT_ALL_SERVICES_OPTION,
  countryManuallySelected: false,
  serviceManuallySelected: false,
  selectedServiceIndex: -1,
  preferListFirstCountry: false,
};

const selectionEquals = (
  left: ConsultBrowserSelection,
  right: ConsultBrowserSelection,
): boolean =>
  left.selectedCountry === right.selectedCountry &&
  left.selectedService === right.selectedService &&
  left.countryManuallySelected === right.countryManuallySelected &&
  left.serviceManuallySelected === right.serviceManuallySelected &&
  left.selectedServiceIndex === right.selectedServiceIndex &&
  left.preferListFirstCountry === right.preferListFirstCountry;

export const createConsultBrowserStore = (): ConsultBrowserStore => {
  let selection: ConsultBrowserSelection = { ...INITIAL_SELECTION };
  const listeners = new Set<() => void>();

  return {
    getSelection: (): ConsultBrowserSelection => selection,
    subscribe: (listener: () => void): (() => void) => {
      listeners.add(listener);

      return (): void => {
        listeners.delete(listener);
      };
    },
    updateSelection: (updater): void => {
      const next = updater(selection);

      if (next === selection || selectionEquals(selection, next)) {
        return;
      }

      selection = next;
      listeners.forEach((listener: () => void): void => {
        listener();
      });
    },
  };
};

const ConsultBrowserSelectionContext =
  React.createContext<ConsultBrowserStore | null>(null);

export const ConsultBrowserSelectionProvider = ({
  children,
}: {
  children: React.ReactNode;
}): React.ReactElement => {
  const storeRef = useRef<ConsultBrowserStore | null>(null);

  if (storeRef.current === null) {
    storeRef.current = createConsultBrowserStore();
  }

  return (
    <ConsultBrowserSelectionContext.Provider value={storeRef.current}>
      {children}
    </ConsultBrowserSelectionContext.Provider>
  );
};

interface ConsultBrowserSelectionApi {
  selection: ConsultBrowserSelection;
  getSelection: ConsultBrowserStore['getSelection'];
  updateSelection: ConsultBrowserStore['updateSelection'];
}

// The primary tab and the secondary consult page each mount a browser.
// A store above both screens keeps plan filters and the doctor query in step.
// Screens rendered without the provider keep a private store so isolated
// tests do not leak selection into one another.
export const useConsultBrowserSelection = (): ConsultBrowserSelectionApi => {
  const sharedStore = useContext(ConsultBrowserSelectionContext);
  const localStoreRef = useRef<ConsultBrowserStore | null>(null);

  if (sharedStore === null && localStoreRef.current === null) {
    localStoreRef.current = createConsultBrowserStore();
  }

  const store = sharedStore ?? localStoreRef.current!;
  const selection = useSyncExternalStore(
    store.subscribe,
    store.getSelection,
    store.getSelection,
  );

  return {
    selection,
    getSelection: store.getSelection,
    updateSelection: store.updateSelection,
  };
};

