            <TouchableOpacity
              activeOpacity={0.8}
              accessibilityLabel={constants.i18n.t('openingHoursService')}
              accessibilityRole="button"
              onPress={handleOpeningHoursPress}
              style={styles.openingHoursButton}
              testID="consult-opening-hours-button"
            >
              <View style={styles.openingHoursContent}>
                <SVGClockFillIcon height={16} width={16} />
                <AppText
                  ellipsizeMode="tail"
                  numberOfLines={1}
                  style={styles.openingHoursText}
                >
                  {constants.i18n.t('openingHoursService')}
                </AppText>
              </View>
              <SVGArrowRightOutlineIcon height={16} width={16} />
            </TouchableOpacity>
          </View>
        }
      />
    </View>
  );
};

export default ConsultBrowser;

