import {
  CONSULT_ALL_SERVICES_OPTION,
  createConsultBrowserStore,
} from '../src/screens/consult-screen/consult-browser-selection';

describe('createConsultBrowserStore', () => {
  test('starts without a country and with all services selected', () => {
    expect(createConsultBrowserStore().getSelection()).toMatchObject({
      selectedCountry: undefined,
      selectedService: CONSULT_ALL_SERVICES_OPTION,
    });
  });

  test('notifies every subscriber when the selection changes', () => {
    const store = createConsultBrowserStore();
    const primaryListener = jest.fn();
    const secondaryListener = jest.fn();

    store.subscribe(primaryListener);
    store.subscribe(secondaryListener);
    store.updateSelection((current) => ({
      ...current,
      selectedCountry: 'Austria',
    }));

    expect([
      primaryListener.mock.calls.length,
      secondaryListener.mock.calls.length,
    ]).toEqual([1, 1]);
  });

  test('skips notifications when an update keeps the same values', () => {
    const store = createConsultBrowserStore();
    const listener = jest.fn();

    store.subscribe(listener);
    store.updateSelection((current) => ({ ...current }));

    expect(listener).not.toHaveBeenCalled();
  });

  test('stops notifying a subscriber after it unsubscribes', () => {
    const store = createConsultBrowserStore();
    const listener = jest.fn();
    const unsubscribe = store.subscribe(listener);

    unsubscribe();
    store.updateSelection((current) => ({
      ...current,
      selectedService: 'Cardiology',
    }));

    expect(listener).not.toHaveBeenCalled();
  });
});

